// Listen to block events
MinecraftForge.EVENT_BUS.addListener(this::onBlockPlace);
MinecraftForge.EVENT_BUS.addListener(this::onBlockBreak);
MinecraftForge.EVENT_BUS.addListener(this::onBlockDrops);

private void onBlockPlace(BlockEvent.EntityPlaceEvent event) {
    Level world = event.getLevel();
    BlockPos pos = event.getPos();
    BlockState state = event.getState();

    // Example: Prevent placing blocks in certain areas
    if (pos.getY() > 100 && !world.isClientSide()) {
        event.setCanceled(true);
    }
}

private void onBlockBreak(BlockEvent.BreakEvent event) {
    Player player = event.getPlayer();
    Level world = event.getLevel();
    BlockPos pos = event.getPos();
    BlockState state = event.getState();

    // Example: Custom drop logic
    if (state.is(Blocks.DIAMOND_ORE)) {
        event.setExpToDrop(10); // Increase XP
    }
}

private void onBlockDrops(BlockEvent.BlockDropsEvent event) {
    // Modify or add custom drops
    if (event.getState().is(Blocks.COBWEB)) {
        event.getDrops().add(new ItemStack(Items.STRING, 2));
    }
}
